#!/usr/bin/env python3
# SPDX-License-Identifier: LGPL-2.0-or-later
# colorburst: clean-room generator for the VnLexiName -> Unicode / no-tone / root
# tables that the LGPL ukengine needs but that upstream ships in the GPL-2.0
# data.cpp / charset.cpp. We derive every value from the *self-documenting*
# VnLexiName enum names (public LGPL interface in vnlexi.h) plus the Unicode
# standard, so nothing is copied out of the GPL data files.
import re, sys, unicodedata

vnlexi = sys.argv[1]
names = []
for line in open(vnlexi):
    m = re.match(r'\s*(vnl_[A-Za-z0-9]+),', line)
    if m:
        n = m.group(1)
        if n in ('vnl_nonVnChar', 'vnl_lastChar'):
            continue
        names.append(n)

idx = {n: i for i, n in enumerate(names)}

TONE = {'1': '́', '2': '̀', '3': '̉', '4': '̃', '5': '̣'}
# modifier suffix letter -> combining diacritic on the base vowel
MOD = {'r': '̂', 'b': '̆', 'h': '̛'}  # circumflex, breve, horn

def decompose(name):
    """Return (base_letter, case_is_upper, mod_char_or_None, tone_or_'0')."""
    core = name[len('vnl_'):]
    tone = '0'
    if core[-1] in TONE:
        tone = core[-1]
        core = core[:-1]
    # đ / Đ
    if core in ('DD', 'dd'):
        return ('Đ' if core == 'DD' else 'đ', core == 'DD', None, tone)
    upper = core[0].isupper()
    base = core[0].lower()
    mod = None
    if len(core) == 2:
        mod = core[1].lower()   # r/b/h
    base_ch = base.upper() if upper else base
    return (base_ch, upper, mod, tone)

def codepoint(name):
    base_ch, upper, mod, tone = decompose(name)
    if base_ch in ('Đ', 'đ'):
        s = base_ch
    else:
        s = base_ch
        if mod:
            s = s + MOD[mod]
        if tone != '0':
            s = s + TONE[tone]
        s = unicodedata.normalize('NFC', s)
    if len(s) != 1:
        raise SystemExit(f'{name}: did not compose to single codepoint: {s!r}')
    return ord(s)

def notone_name(name):
    core = name[len('vnl_'):]
    if core[-1] in TONE:
        return 'vnl_' + core[:-1]
    return name

def root_name(name):
    """Strip tone AND vowel modifier (roof/breve/horn) -> plain base letter."""
    base_ch, upper, mod, tone = decompose(name)
    core = name[len('vnl_'):]
    if core in ('DD', 'dd'):
        return name  # root of đ is đ itself in upstream (no plain-d fold)
    letter = core[0]  # preserves case, drops any modifier/tone
    return 'vnl_' + letter

out = []
out.append('// SPDX-License-Identifier: LGPL-2.0-or-later')
out.append('// colorburst: clean-room replacement for the Vietnamese output/fold')
out.append('// tables. Generated by gen_tables.py from vnlexi.h; NOT copied from the')
out.append('// GPL-2.0 data.cpp/charset.cpp. See README.chromium.')
out.append('#include "charset.h"')
out.append('#include "vnlexi.h"')
out.append('')
out.append(f'// One codepoint per VnLexiName (0..{len(names)-1}).')
out.append('const unsigned int UkVnLexiToUnicode[] = {')
for n in names:
    out.append(f'    0x{codepoint(n):04X}, // {n}')
out.append('};')
out.append('const int UkVnLexiCount = %d;' % len(names))
out.append('')
out.append('int StdVnNoTone[] = {')
for n in names:
    out.append(f'    {idx[notone_name(n)]}, // {n} -> {notone_name(n)}')
out.append('};')
out.append('')
out.append('int StdVnRootChar[] = {')
for n in names:
    rn = root_name(n)
    out.append(f'    {idx[rn]}, // {n} -> {rn}')
out.append('};')
out.append('')
print('\n'.join(out))
